 */
scwin.init_datefmt_cal_foundDd = function () { $c.date.checkCalendarFormat("cal_foundDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.setRegNoData();
        scwin.setInitDisplay();
        const com_attr_tp_cd = $c.util.getComponent('slc_comAttrTpCd').getValue();
        if (com_attr_tp_cd === '5' || com_attr_tp_cd === '7') {
            (($c.util.getComponent('ipt_regNot')) && ($c.util.getComponent('ipt_regNot')).setValue ? ($c.util.getComponent('ipt_regNot')).setValue((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
            $c.util.getComponent('ipt_notiSchdlDd').setValue("");
            $c.util.getComponent('ipt_nregRsn').setValue("");
            (($c.util.getComponent('ipt_regNot')) && ($c.util.getComponent('ipt_regNot')).setDisabled ? ($c.util.getComponent('ipt_regNot')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
        }
        scwin.setAcntcls_mm();
        let found_dd = $c.util.getComponent('cal_foundDd').getValue();
        if (found_dd.length === 8) {
            found_dd = found_dd.substring(0, 4) + "-" + found_dd.substring(4, 6) + "-" + found_dd.substring(6, 8);
        }
        $c.util.getComponent('cal_foundDd').setValue(found_dd);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05400.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 2개다(corpupd#corpupdreqcheck vs corpupd#corpupdreqsave) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":1
        ,"mmenu":2
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf05400' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.reg_button = $c.util.getComponent('reg_button');
        scwin.init_fillGen();
        scwin.init_conds();
        scwin.init_datefmt_cal_foundDd();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf05400.onpageload' });
    }
};

