/**
 * @method
 * @name tx_check_form
 * @description check form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_check_form = async function () {
    const sbmOptions = {
        id: "tx_check_form",
        method: "post",
        action: "/common/corpUpd.do?method=corpUpdReqCheck",
        ref: "dma_checkFormReq",
        target: "dlt_comAttrTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
