 * @name setRegNoData
 * @description set Reg No Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.setRegNoData = function () {
    let corpRegNo = $c.util.getComponent('ipt_corpRegNoP').getValue(); if (corpRegNo == null) { corpRegNo = ''; }
    if (corpRegNo !== '') {
        const corpRegNos = corpRegNo.split("-");
        if (corpRegNos.length > 0) {
            $c.util.getComponent('ipt_corpRegNo1').setValue(corpRegNos[0]);
        }
        if (corpRegNos.length > 1) {
            $c.util.getComponent('ipt_corpRegNo2').setValue(corpRegNos[1]);
        }
        $c.util.getComponent('ipt_corpRegNoE').setValue(corpRegNo);
    }
    let bzRegNo = $c.util.getComponent('ipt_bzRegNoP').getValue(); if (bzRegNo == null) { bzRegNo = ''; }
    if (bzRegNo !== '') {
        const bzRegNos = bzRegNo.split("-");
        if (bzRegNos.length > 0) {
            $c.util.getComponent('ipt_bzRegNo1').setValue(bzRegNos[0]);
        }
        if (bzRegNos.length > 1) {
            $c.util.getComponent('ipt_bzRegNo2').setValue(bzRegNos[1]);
        }
        if (bzRegNos.length > 2) {
            $c.util.getComponent('ipt_bzRegNo3').setValue(bzRegNos[2]);
        }
        $c.util.getComponent('ipt_bzRegNoE').setValue(corpRegNo);
    }
};

