        $c.util.getComponent("ipt_isurEngNm").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_isurEngAbbrv').getValue()) === 0) {
        await $c.win.alert("발행기관 영문약명을 입력하세요.");
        $c.util.getComponent("ipt_isurEngAbbrv").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_isurEngAbbrv').getValue()) > 40) {
        await $c.win.alert("발행기관 영문약명을 40자 이내로 입력하세요.");
        $c.util.getComponent("ipt_isurEngAbbrv").focus();
        return false;
    }
    if (!(String($c.util.getComponent('ipt_regNot').getValue() || "") !== "")) {
        if ($c.util.getComponent('ipt_cntrCd').getValue()=== "410") {
            if ($c.util.getComponent('slc_comAttrTpCd').getSelectedIndex() !== 5 && $c.util.getComponent('slc_comAttrTpCd').getSelectedIndex() !== 7) {
                if ($c.str.getByteLength($c.util.getComponent('ipt_corpRegNo1').getValue()) === 0 || $c.str.getByteLength($c.util.getComponent('ipt_corpRegNo2').getValue()) === 0) {
                    await $c.win.alert("법인등록번호를 입력하세요.");
                    $c.util.getComponent("ipt_corpRegNo1").focus();
                    return false;
                }
                if ($c.str.getByteLength($c.util.getComponent('ipt_corpRegNo1').getValue()) + $c.str.getByteLength($c.util.getComponent('ipt_corpRegNo2').getValue()) !== 13) {
                    await $c.win.alert("법인등록번호는 13자리입니다.");
                    $c.util.getComponent("ipt_corpRegNo1").focus();
                    return false;
                }
                if ($c.str.getByteLength($c.util.getComponent('ipt_bzRegNo1').getValue()) === 0 || $c.str.getByteLength($c.util.getComponent('ipt_bzRegNo2').getValue()) === 0 || $c.str.getByteLength($c.util.getComponent('ipt_bzRegNo3').getValue()) === 0) {
                    await $c.win.alert("사업자등록번호를 입력하세요.");
                    $c.util.getComponent("ipt_bzRegNo1").focus();
                    return false;
                }
                if ($c.str.getByteLength($c.util.getComponent('ipt_bzRegNo1').getValue()) + $c.str.getByteLength($c.util.getComponent('ipt_bzRegNo2').getValue()) + $c.str.getByteLength($c.util.getComponent('ipt_bzRegNo3').getValue()) !== 10) {
                    await $c.win.alert("사업자등록번호는 10자리입니다.");
                    $c.util.getComponent("ipt_bzRegNo1").focus();
                    return false;
                }
            }
            if ($c.str.getByteLength($c.util.getComponent('ipt_zipcd').getValue()) === 0) {
                await $c.win.alert("우편번호를 입력하세요.");
                $c.util.getComponent("ipt_zipcd").focus();
                return false;
            }
            $c.util.getComponent("dma_checkFormReq").set("corpRegNo", scwin.getCorpRegNo());
            $c.util.getComponent("dma_checkFormReq").set("bzRegNo", scwin.getBzRegNo());
        } else {
            $c.util.getComponent("ipt_corpRegNo1").setValue('');
            $c.util.getComponent("ipt_corpRegNo2").setValue('');
            $c.util.getComponent("dma_checkFormReq").set("corpRegNo", $c.util.getComponent('ipt_corpRegNoE').getValue());
            $c.util.getComponent("ipt_bzRegNo1").setValue('');
            $c.util.getComponent("ipt_bzRegNo2").setValue('');
            $c.util.getComponent("ipt_bzRegNo3").setValue('');
            $c.util.getComponent("dma_checkFormReq").set("bzRegNo", $c.util.getComponent('ipt_bzRegNoE').getValue());
            $c.util.getComponent("ipt_zipcd").setValue('');
        }
        $c.util.getComponent("ipt_regNot").setValue(false);
    } else {
        $c.util.getComponent("ipt_corpRegNo1").setValue('');
        $c.util.getComponent("ipt_corpRegNo2").setValue('');
        $c.util.getComponent("ipt_corpRegNoE").setValue('');
        $c.util.getComponent("ipt_bzRegNo1").setValue('');
        $c.util.getComponent("ipt_bzRegNo2").setValue('');
        $c.util.getComponent("ipt_bzRegNo3").setValue('');
        $c.util.getComponent("ipt_bzRegNoE").setValue('');
        if ($c.str.getByteLength($c.util.getComponent("dma_checkFormReq").get("nregRsn")) === 0) {
            await $c.win.alert('미등록 사유를 입력하십시오');
            await scwin.popNonRegRsn();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent("dma_checkFormReq").get("notiSchdlDd")) === 0) {
            await $c.win.alert('통보예정일을 입력하십시오');
            await scwin.popNonRegRsn();
            return false;
        }
        $c.util.getComponent("ipt_regNot").setValue(true);
    }
    if ($c.util.getComponent('ipt_cntrCd').getValue()=== "410") {
        if ($c.str.getByteLength($c.util.getComponent('ipt_addr').getValue()) === 0) {
            await $c.win.alert("주소를 입력하세요.");
            $c.util.getComponent("ipt_addr").focus();
            return false;
        }
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_engAddr').getValue()) === 0) {
            await $c.win.alert("영문주소를 입력하세요.");
            $c.util.getComponent("ipt_engAddr").focus();
            return false;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_dtlAddr').getValue()) === 0) {

    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_ceoNm').getValue()) === 0) {
        await $c.win.alert("대표이사명을 입력하세요.");
        $c.util.getComponent("ipt_ceoNm").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_telNo').getValue()) === 0 && $c.util.getComponent('ipt_cntrCd').getValue()!== '410') {
        await $c.win.alert("대표전화를 입력하세요.");
        $c.util.getComponent("ipt_telNo").focus();
        return false;
    }
    if ($c.util.getComponent('ipt_cntrCd').getValue()=== '410') {
        if ($c.str.getByteLength($c.util.getComponent('ipt_telNo1').getValue()) === 0) {
            await $c.win.alert("대표전화를 입력하세요.");
            $c.util.getComponent("ipt_telNo1").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_telNo2').getValue()) === 0) {
            await $c.win.alert("대표전화를 입력하세요.");
            $c.util.getComponent("ipt_telNo2").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_telNo3').getValue()) === 0) {
            await $c.win.alert("대표전화를 입력하세요.");
            $c.util.getComponent("ipt_telNo3").focus();
            return false;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_foundDd').getValue()) === 0) {
        await $c.win.alert(" 설립일을 입력하세요.");
        ($c.util.getComponent('cal_foundDd') && $c.util.getComponent('cal_foundDd').setFocus ? $c.util.getComponent('cal_foundDd').setFocus() : ($c.util.getComponent('cal_foundDd') && $c.util.getComponent('cal_foundDd').focus ? $c.util.getComponent('cal_foundDd').focus() : console.warn('[sdd] focus 대상 미해결: cal_foundDd')));
        return false;
    }
    const cnt = parseInt($c.util.getComponent('ipt_acntclsCnt').getValue(), 10);
    for (let i = 1; i < cnt + 1; i++) {
        if ($c.str.getByteLength($('#acntcls_mm' + i).val() + "") === 0) {
            await $c.win.alert("결산월을 선택해 주세요.");
            $c.util.getComponent("ipt_acntclsCnt").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
            return false;
        }
    }
    for (let i = 1; i <= cnt; i++) {
        for (let j = cnt; j >= 1; j--) {
            if (i !== j) {
                if ($('#acntcls_mm' + i).val() !== '') {
                    if ($('#acntcls_mm' + j).val() !== '') {
                        if ($('#acntcls_mm' + i).val() === $('#acntcls_mm' + j).val()) {
                            await $c.win.alert("동일한 결산월이 존재합니다.\n결산월을 확인해주세요!");
                            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                            return false;
                        }
                    }
                }
            }
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_comAttrTpCd').getValue()) === 0) {
        await $c.win.alert("회사 속성을 선택해 주십시오.");
        document.com_attr_tp_cd.focus();
        return false;
    }
    if ($("td#transstk_agnt_cd input:checked").val() == null || $c.str.getByteLength($("td#transstk_agnt_cd input:checked").val()) === 0) {
        await $c.win.alert("명의개서회사를 입력하세요.");
        $("#transstk_agnt_cd_1").focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name getCorpRegNo
 * @description get Corp Reg No 처리
 * @returns {void}
 * @hidden N
 */
scwin.getCorpRegNo = function () {
    const sCorpRegNo = $c.util.getComponent('ipt_corpRegNo1').getValue() + $c.util.getComponent('ipt_corpRegNo2').getValue();
    const sCorpRegNoOrg = $c.util.getComponent('ipt_corpRegNoOrignal').getValue();
    let sRtn = "";
    if (sCorpRegNo.length === 13 && sCorpRegNo.indexOf("*") > -1 && sCorpRegNoOrg.length === 13) {
        for (let i = 0; i < sCorpRegNoOrg.length; i++) {
            const cCharAt = sCorpRegNo.charAt(i);
            if (cCharAt === '*') {
                sRtn += sCorpRegNoOrg.charAt(i);
            } else {
                sRtn += cCharAt;
            }
        }
    } else {
        sRtn = sCorpRegNo;
    }
    return sRtn;
};

/**
 * @method
 * @name getBzRegNo
 * @description get Bz Reg No 처리
 * @returns {void}
 * @hidden N
 */
scwin.getBzRegNo = function () {
    const sBzRegNo = $c.util.getComponent('ipt_bzRegNo1').getValue() + $c.util.getComponent('ipt_bzRegNo2').getValue() + $c.util.getComponent('ipt_bzRegNo3').getValue();
    const sBzRegNoOrg = $c.util.getComponent('ipt_bzRegNoOrignal').getValue();
    let sRtn = "";
    if (sBzRegNo.length === 10 && sBzRegNo.indexOf("*") > -1 && sBzRegNoOrg.length === 10) {
        for (let i = 0; i < sBzRegNoOrg.length; i++) {
            const cCharAt = sBzRegNo.charAt(i);
            if (cCharAt === '*') {
                sRtn += sBzRegNoOrg.charAt(i);
            } else {
                sRtn += cCharAt;
            }
        }
    } else {
        sRtn = sBzRegNo;
    }
    return sRtn;
};

/**
 * @method
 * @name check_form
 * @description check form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.check_form = async function () {
    const fm = (document.JLDINF05400 || { elements: [] });
    if ($c.util.getComponent('ipt_cntrCd').getValue()=== '410') {
        $c.util.getComponent("dma_checkFormReq").set("corpRegNoP", $c.util.getComponent('ipt_corpRegNo1').getValue()+ '-' + $c.util.getComponent('ipt_corpRegNo2').getValue());
        $c.util.getComponent("dma_checkFormReq").set("bzRegNoP", $c.util.getComponent('ipt_bzRegNo1').getValue()+ '-' + $c.util.getComponent('ipt_bzRegNo2').getValue()+ '-' + $c.util.getComponent('ipt_bzRegNo3').getValue());
        $c.util.getComponent("ipt_telNo").setValue($c.util.getComponent('ipt_telNo1').getValue()+ "-" + $c.util.getComponent('ipt_telNo2').getValue()+ "-" + $c.util.getComponent('ipt_telNo3').getValue());
    }
    if (!await scwin.dataValidation()) {
        return;
    }
    if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
        return;
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return;
    }
    let tmp = '';
    const cnt = parseInt($c.util.getComponent('ipt_acntclsCnt').getValue(), 10);
    for (let i = 1; i < cnt + 1; i++) {
        if (i === 1) {
            tmp = tmp + $('#acntcls_mm' + i).val();
        } else {
            tmp = tmp + ', ' + $('#acntcls_mm' + i).val();
        }
    }
    $c.util.getComponent('ipt_acntclsTmp').setValue(tmp);
    if (await $c.win.confirm("신청하시겠습니까?")) {
        const width = 800;
        const height = 700;
        const left = (screen.width - width) / 3;
        const top = (screen.height - height) / 3;
        let _popupWindow;
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        _popupWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/common/corpUpd.do?method=corpUpdReqCheck", unresolved: "nav:" + "/common/corpUpd.do?method=corpUpdReqCheck" }; })();
        fm.action = '/common/corpUpd.do?method=corpUpdReqCheck';

    }
};

